class LeaseRegistry:
    def __init__(self):
        self._leases = {}

    def acquire(self, key, owner, now, ttl):
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        current = self._leases.get(key)
        if current and current["expires_at"] > now and current["owner"] != owner:
            return None
        token = 1
        self._leases[key] = {"owner": owner, "token": token, "expires_at": now + ttl}
        return token

    def renew(self, key, owner, token, now, ttl):
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        current = self._leases.get(key)
        if not current or current["owner"] != owner or current["token"] != token:
            return False
        current["expires_at"] = now + ttl
        return True

    def release(self, key, owner, token):
        current = self._leases.get(key)
        if not current or current["owner"] != owner or current["token"] != token:
            return False
        del self._leases[key]
        return True

class BatchStore:
    def __init__(self, initial=None):
        self.data = dict(initial or {})
        self.observers = []

    def subscribe(self, observer):
        self.observers.append(observer)

    def apply(self, operations):
        for operation in operations:
            kind = operation[0]
            key = operation[1]
            if kind == "set":
                self.data[key] = operation[2]
            elif kind == "delete":
                self.data.pop(key, None)
            else:
                raise ValueError("unknown operation")
        snapshot = dict(self.data)
        for observer in self.observers:
            observer(self.data)
        return snapshot

def plan_batches(graph, capacity):
    if capacity < 1:
        raise ValueError("capacity")
    jobs = sorted(graph)
    return [jobs[index:index + capacity] for index in range(0, len(jobs), capacity)]

class VersionedStore:
    def __init__(self, initial=None):
        self._data = dict(initial or {})
        self._version = 0

    def read(self, key):
        return self._data.get(key)

    def begin(self):
        return {"version": self._version, "data": self._data}

    def commit(self, snapshot, writes):
        if snapshot["version"] != self._version:
            return False
        for key, value in writes.items():
            if value is None:
                self._data.pop(key, None)
            else:
                self._data[key] = value
        self._version += 1
        return True
